WITH {
  name: 'TIANSHENG INDUSTRY AND TRADING CO., LTD.',
  properties: { internal_id: '1001256' }
} AS t
MATCH (e:Entity)-[:same_as]->(t)
OR MATCH (e:Entity)-[:registered_address]->(a:Address)<-[:same_as]-(t)
OR MATCH (e:Entity)-[:same_name_as]->(o:Other)<-[:connected_to]-(t)
OR MATCH (e:Entity)-[:same_name_as]->(o2:Other)<-[r:same_as]-(t)
RETURN e.properties.internal_id AS internalId

